// 2D compressible Euler, Rayleigh-Taylor instability. Finite volume, MUSCL (MC limiter on
// primitive vars) + HLLC Riemann solver + SSP-RK3, gravity source g=+1 in y.
// x periodic, y reflective walls (ghost pressure extrapolated hydrostatically).
// usage: ./rt NX NY TEND outprefix [perturb=1]
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <string.h>
#include <omp.h>

#define G 2
static const double gam = 1.4, grav = 1.0, LX = 0.25, LY = 1.0;
static int NX, NY, SX, SY;
static double dx, dy;
#define ID(i, j) ((j) * SX + (i))

static inline double mc(double a, double b) {
    if (a * b <= 0) return 0;
    double s = a > 0 ? 1 : -1;
    a = fabs(a); b = fabs(b);
    double m = fmin(2 * a, 2 * b); m = fmin(m, 0.5 * (a + b));
    return s * m;
}

// HLLC flux in normal direction; primitive states (r, un, ut, p)
static inline void hllc(double rl, double ul, double vl, double pl, double rr, double ur, double vr,
                        double pr, double *f) {
    double cl = sqrt(gam * pl / rl), cr = sqrt(gam * pr / rr);
    double El = pl / (gam - 1) + 0.5 * rl * (ul * ul + vl * vl);
    double Er = pr / (gam - 1) + 0.5 * rr * (ur * ur + vr * vr);
    double SL = fmin(ul - cl, ur - cr), SR = fmax(ul + cl, ur + cr);
    double SM = (pr - pl + rl * ul * (SL - ul) - rr * ur * (SR - ur)) / (rl * (SL - ul) - rr * (SR - ur));
    if (SL >= 0) {
        f[0] = rl * ul; f[1] = rl * ul * ul + pl; f[2] = rl * ul * vl; f[3] = (El + pl) * ul;
    } else if (SR <= 0) {
        f[0] = rr * ur; f[1] = rr * ur * ur + pr; f[2] = rr * ur * vr; f[3] = (Er + pr) * ur;
    } else if (SM >= 0) {
        double fac = rl * (SL - ul) / (SL - SM);
        double Us[4] = {fac, fac * SM, fac * vl, fac * (El / rl + (SM - ul) * (SM + pl / (rl * (SL - ul))))};
        double U[4] = {rl, rl * ul, rl * vl, El};
        double F[4] = {rl * ul, rl * ul * ul + pl, rl * ul * vl, (El + pl) * ul};
        for (int k = 0; k < 4; k++) f[k] = F[k] + SL * (Us[k] - U[k]);
    } else {
        double fac = rr * (SR - ur) / (SR - SM);
        double Us[4] = {fac, fac * SM, fac * vr, fac * (Er / rr + (SM - ur) * (SM + pr / (rr * (SR - ur))))};
        double U[4] = {rr, rr * ur, rr * vr, Er};
        double F[4] = {rr * ur, rr * ur * ur + pr, rr * ur * vr, (Er + pr) * ur};
        for (int k = 0; k < 4; k++) f[k] = F[k] + SR * (Us[k] - U[k]);
    }
}

static double *W[4]; // primitive work arrays r,u,v,p with ghosts

static void to_prim(double **U) {
#pragma omp parallel for
    for (int j = G; j < NY + G; j++)
        for (int i = G; i < NX + G; i++) {
            int c = ID(i, j);
            double r = U[0][c], u = U[1][c] / r, v = U[2][c] / r;
            W[0][c] = r; W[1][c] = u; W[2][c] = v;
            W[3][c] = (gam - 1) * (U[3][c] - 0.5 * r * (u * u + v * v));
        }
    // y walls: mirror, flip v, hydrostatic pressure extrapolation
    for (int g = 0; g < G; g++) {
        for (int i = G; i < NX + G; i++) {
            int gb = ID(i, G - 1 - g), ib = ID(i, G + g);
            int gt = ID(i, NY + G + g), it = ID(i, NY + G - 1 - g);
            double d = (2 * g + 1) * dy;
            W[0][gb] = W[0][ib]; W[1][gb] = W[1][ib]; W[2][gb] = -W[2][ib];
            W[3][gb] = W[3][ib] - W[0][ib] * grav * d;
            W[0][gt] = W[0][it]; W[1][gt] = W[1][it]; W[2][gt] = -W[2][it];
            W[3][gt] = W[3][it] + W[0][it] * grav * d;
        }
    }
    // x periodic
    for (int j = 0; j < SY; j++)
        for (int g = 0; g < G; g++)
            for (int k = 0; k < 4; k++) {
                W[k][ID(g, j)] = W[k][ID(NX + g, j)];
                W[k][ID(NX + G + g, j)] = W[k][ID(G + g, j)];
            }
}

// compute dU/dt into R
static void rhs(double **U, double **R) {
    to_prim(U);
    for (int k = 0; k < 4; k++) memset(R[k], 0, sizeof(double) * SX * SY);
    // x-fluxes: interface between i-1 and i, for i=G..NX+G
#pragma omp parallel for
    for (int j = G; j < NY + G; j++) {
        double fprev[4];
        for (int i = G; i <= NX + G; i++) {
            double L[4], Rr[4], f[4];
            for (int k = 0; k < 4; k++) {
                double *w = W[k];
                int a = ID(i - 2, j), b = ID(i - 1, j), c = ID(i, j), d = ID(i + 1, j);
                double sb = mc(w[b] - w[a], w[c] - w[b]);
                double sc = mc(w[c] - w[b], w[d] - w[c]);
                L[k] = w[b] + 0.5 * sb; Rr[k] = w[c] - 0.5 * sc;
            }
            hllc(L[0], L[1], L[2], L[3], Rr[0], Rr[1], Rr[2], Rr[3], f);
            if (i > G) {
                int c = ID(i - 1, j);
                for (int k = 0; k < 4; k++) R[k][c] -= (f[k] - fprev[k]) / dx;
            }
            memcpy(fprev, f, sizeof f);
        }
    }
    // y-fluxes
#pragma omp parallel for
    for (int i = G; i < NX + G; i++) {
        double fprev[4];
        for (int j = G; j <= NY + G; j++) {
            double L[4], Rr[4], f[4], fy[4];
            for (int k = 0; k < 4; k++) {
                double *w = W[k];
                int a = ID(i, j - 2), b = ID(i, j - 1), c = ID(i, j), d = ID(i, j + 1);
                double sb = mc(w[b] - w[a], w[c] - w[b]);
                double sc = mc(w[c] - w[b], w[d] - w[c]);
                L[k] = w[b] + 0.5 * sb; Rr[k] = w[c] - 0.5 * sc;
            }
            // normal = v, tangential = u
            hllc(L[0], L[2], L[1], L[3], Rr[0], Rr[2], Rr[1], Rr[3], f);
            fy[0] = f[0]; fy[1] = f[2]; fy[2] = f[1]; fy[3] = f[3];
            if (j == G || j == NY + G) fy[0] = fy[1] = fy[3] = 0; // exact wall flux (only pressure)
            if (j > G) {
                int c = ID(i, j - 1);
                for (int k = 0; k < 4; k++) R[k][c] -= (fy[k] - fprev[k]) / dy;
            }
            memcpy(fprev, fy, sizeof fy);
        }
    }
    // gravity source (+y)
#pragma omp parallel for
    for (int j = G; j < NY + G; j++)
        for (int i = G; i < NX + G; i++) {
            int c = ID(i, j);
            R[2][c] += U[0][c] * grav;
            R[3][c] += U[2][c] * grav;
        }
}

static double maxdt(double **U, double cfl) {
    to_prim(U);
    double m = 0;
#pragma omp parallel for reduction(max : m)
    for (int j = G; j < NY + G; j++)
        for (int i = G; i < NX + G; i++) {
            int c = ID(i, j);
            double cs = sqrt(gam * W[3][c] / W[0][c]);
            double s = (fabs(W[1][c]) + cs) / dx + (fabs(W[2][c]) + cs) / dy;
            if (s > m) m = s;
        }
    return cfl / m;
}

int main(int argc, char **argv) {
    NX = atoi(argv[1]); NY = atoi(argv[2]);
    double tend = atof(argv[3]);
    const char *pre = argv[4];
    int perturb = argc > 5 ? atoi(argv[5]) : 1;
    SX = NX + 2 * G; SY = NY + 2 * G; dx = LX / NX; dy = LY / NY;
    double *U[4], *U1[4], *R[4];
    for (int k = 0; k < 4; k++) {
        U[k] = calloc(SX * SY, sizeof(double)); U1[k] = calloc(SX * SY, sizeof(double));
        R[k] = calloc(SX * SY, sizeof(double)); W[k] = calloc(SX * SY, sizeof(double));
    }
    // IC: point values at cell centres
    for (int j = G; j < NY + G; j++)
        for (int i = G; i < NX + G; i++) {
            double x = (i - G + 0.5) * dx, y = (j - G + 0.5) * dy;
            double r = 2.0 + (1.0 - 2.0) * 0.5 * (1 + tanh(50 * (y - 0.5)));
            double p = y < 0.5 ? 2 * y + 1 : y + 1.5;
            double cs = sqrt(gam * p / r);
            double s = sin(M_PI * y);
            double v = perturb ? -0.025 * cs * cos(8 * M_PI * x) * pow(s, 6) : 0.0;
            int c = ID(i, j);
            U[0][c] = r; U[1][c] = 0; U[2][c] = r * v; U[3][c] = p / (gam - 1) + 0.5 * r * v * v;
        }
    char fn[512];
    sprintf(fn, "%s_diag.txt", pre);
    FILE *fd = fopen(fn, "w");
    sprintf(fn, "%s_snap.bin", pre);
    FILE *fs = fopen(fn, "wb");
    double t = 0, cfl = 0.4;
    int nsnap = 13, isnap = 0; // snapshots every 0.25
    double dtsnap = tend / (nsnap - 1), tdiag = 0, dtdiag = 0.01;
    long step = 0;
    int N = NX * NY;
    double *buf = malloc(sizeof(double) * N * 4);
    while (1) {
        // diagnostics
        if (t >= tdiag - 1e-12 || t >= tend - 1e-14) {
            double M = 0, Mx = 0, My = 0, E = 0, Ep = 0, KE = 0, vmax = 0, a1 = 0, mix = 0, ymin = 1, ymax = 0;
            for (int j = G; j < NY + G; j++) {
                double y = (j - G + 0.5) * dy, va = 0;
                for (int i = G; i < NX + G; i++) {
                    int c = ID(i, j);
                    double x = (i - G + 0.5) * dx, r = U[0][c];
                    M += r; Mx += U[1][c]; My += U[2][c]; E += U[3][c];
                    Ep += -r * grav * y;
                    KE += 0.5 * (U[1][c] * U[1][c] + U[2][c] * U[2][c]) / r;
                    double vv = fabs(U[2][c] / r); if (vv > vmax) vmax = vv;
                    va += U[2][c] / r * cos(8 * M_PI * x);
                    double f = (2.0 - r); // light fraction
                    mix += f * (1 - f);
                    if (f > 0.05 && f < 0.95) { if (y < ymin) ymin = y; if (y > ymax) ymax = y; }
                }
                va = 2 * va / NX;
                if (fabs(va) > fabs(a1)) a1 = va; // max over y of cos-mode amplitude of v
            }
            double dA = dx * dy;
            fprintf(fd, "%.6f %.15e %.15e %.15e %.15e %.15e %.15e %.6e %.6e %.6e %.6f %.6f\n", t, M * dA, Mx * dA, My * dA,
                    E * dA, Ep * dA, KE * dA, vmax, a1, mix * dA / LX * 4, ymin, ymax);
            fflush(fd);
            tdiag += dtdiag;
        }
        if (t >= isnap * dtsnap - 1e-12 && isnap < nsnap) {
            to_prim(U);
            for (int k = 0; k < 4; k++)
                for (int j = 0; j < NY; j++)
                    for (int i = 0; i < NX; i++) buf[k * N + j * NX + i] = W[k][ID(i + G, j + G)];
            fwrite(&t, sizeof(double), 1, fs);
            fwrite(buf, sizeof(double), 4 * N, fs);
            fflush(fs);
            fprintf(stderr, "snap %d t=%.4f step=%ld\n", isnap, t, step);
            isnap++;
        }
        if (t >= tend - 1e-14) break;
        double dt = maxdt(U, cfl);
        double tn = fmin(fmin(t + dt, isnap * dtsnap), tdiag);
        dt = tn - t;
        if (dt <= 0) dt = 1e-14;
        // SSP-RK3
        rhs(U, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++) for (int k = 0; k < 4; k++) U1[k][c] = U[k][c] + dt * R[k][c];
        rhs(U1, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++)
            for (int k = 0; k < 4; k++) U1[k][c] = 0.75 * U[k][c] + 0.25 * (U1[k][c] + dt * R[k][c]);
        rhs(U1, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++)
            for (int k = 0; k < 4; k++) U[k][c] = U[k][c] / 3.0 + 2.0 / 3.0 * (U1[k][c] + dt * R[k][c]);
        t = tn; step++;
        for (int c = 0; c < SX * SY; c++)
            if (!(U[0][c] == U[0][c])) { fprintf(stderr, "NaN at t=%g\n", t); return 1; }
    }
    fclose(fd); fclose(fs);
    fprintf(stderr, "done steps=%ld\n", step);
    return 0;
}

