            double v = perturb ? -0.025 * cs * cos(8 * M_PI * x) * pow(s, 6) : 0.0;
            int c = ID(i, j);
            U[0][c] = r; U[1][c] = 0; U[2][c] = r * v; U[3][c] = p / (gam - 1) + 0.5 * r * v * v;
        }
    char fn[512];
    sprintf(fn, "%s_diag.txt", pre);
    FILE *fd = fopen(fn, "w");
    sprintf(fn, "%s_snap.bin", pre);
    FILE *fs = fopen(fn, "wb");
    double t = 0, cfl = 0.4;
    int nsnap = 13, isnap = 0; // snapshots every 0.25
    double dtsnap = tend / (nsnap - 1), tdiag = 0, dtdiag = 0.01;
    long step = 0;
    int N = NX * NY;
    double *buf = malloc(sizeof(double) * N * 4);
    while (1) {
        // diagnostics
        if (t >= tdiag - 1e-12 || t >= tend - 1e-14) {
            double M = 0, Mx = 0, My = 0, E = 0, Ep = 0, KE = 0, vmax = 0, a1 = 0, mix = 0, ymin = 1, ymax = 0;
            for (int j = G; j < NY + G; j++) {
                double y = (j - G + 0.5) * dy, va = 0;
                for (int i = G; i < NX + G; i++) {
                    int c = ID(i, j);
                    double x = (i - G + 0.5) * dx, r = U[0][c];
                    M += r; Mx += U[1][c]; My += U[2][c]; E += U[3][c];
                    Ep += -r * grav * y;
                    KE += 0.5 * (U[1][c] * U[1][c] + U[2][c] * U[2][c]) / r;
                    double vv = fabs(U[2][c] / r); if (vv > vmax) vmax = vv;
                    va += U[2][c] / r * cos(8 * M_PI * x);
                    double f = (2.0 - r); // light fraction
                    mix += f * (1 - f);
                    if (f > 0.05 && f < 0.95) { if (y < ymin) ymin = y; if (y > ymax) ymax = y; }
                }
                va = 2 * va / NX;
                if (fabs(va) > fabs(a1)) a1 = va; // max over y of cos-mode amplitude of v
            }
            double dA = dx * dy;
            fprintf(fd, "%.6f %.15e %.15e %.15e %.15e %.15e %.15e %.6e %.6e %.6e %.6f %.6f\n", t, M * dA, Mx * dA, My * dA,
                    E * dA, Ep * dA, KE * dA, vmax, a1, mix * dA / LX * 4, ymin, ymax);
            fflush(fd);
            tdiag += dtdiag;
        }
        if (t >= isnap * dtsnap - 1e-12 && isnap < nsnap) {
            to_prim(U);
            for (int k = 0; k < 4; k++)
                for (int j = 0; j < NY; j++)
                    for (int i = 0; i < NX; i++) buf[k * N + j * NX + i] = W[k][ID(i + G, j + G)];
            fwrite(&t, sizeof(double), 1, fs);
            fwrite(buf, sizeof(double), 4 * N, fs);
            fflush(fs);
            fprintf(stderr, "snap %d t=%.4f step=%ld\n", isnap, t, step);
            isnap++;
        }
        if (t >= tend - 1e-14) break;
        double dt = maxdt(U, cfl);
        double tn = fmin(fmin(t + dt, isnap * dtsnap), tdiag);
        dt = tn - t;
        if (dt <= 0) dt = 1e-14;
        // SSP-RK3
        rhs(U, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++) for (int k = 0; k < 4; k++) U1[k][c] = U[k][c] + dt * R[k][c];
        rhs(U1, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++)
            for (int k = 0; k < 4; k++) U1[k][c] = 0.75 * U[k][c] + 0.25 * (U1[k][c] + dt * R[k][c]);
        rhs(U1, R);
#pragma omp parallel for
        for (int c = 0; c < SX * SY; c++)
            for (int k = 0; k < 4; k++) U[k][c] = U[k][c] / 3.0 + 2.0 / 3.0 * (U1[k][c] + dt * R[k][c]);
        t = tn; step++;
        for (int c = 0; c < SX * SY; c++)
            if (!(U[0][c] == U[0][c])) { fprintf(stderr, "NaN at t=%g\n", t); return 1; }
    }
    fclose(fd); fclose(fs);
    fprintf(stderr, "done steps=%ld\n", step);
    return 0;
}

